function TemperatureDisplay({ celsius }) {
  const prevCelsiusRef = useRef(celsius);

  useEffect(() => {
    prevCelsiusRef.current = celsius;
  }, [celsius]);

  const direction =
    celsius > prevCelsiusRef.current ? "rising" :
    celsius < prevCelsiusRef.current ? "falling" : "steady";

  return <p>{celsius}\u00b0C ({direction})</p>;
}

