```jsx
// BEFORE: this exact combination is duplicated in every component that fetches something
function UserProfile({ userId }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetch(`/api/users/${userId}`)
      .then((res) => res.json())
      .then((json) => setData(json))
      .catch((err) => setError(err))
      .finally(() => setLoading(false));
  }, [userId]);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong.</p>;
  return <p>{data.name}</p>;
}

// AFTER: the pattern is extracted once, and reused anywhere it's needed
function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetch(url)
      .then((res) => res.json())
      .then((json) => setData(json))
      .catch((err) => setError(err))
      .finally(() => setLoading(false));
  }, [url]);

  return { data, loading, error };
}

function UserProfile({ userId }) {
  const { data, loading, error } = useFetch(`/api/users/${userId}`);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong.</p>;
  return <p>{data.name}</p>;
}
```

useFetch is nothing more than a function that itself calls useState three times and useEffect once, bundled behind one name and one return shape. UserProfile (and any other component with the same fetch-and-track need) can now just call `useFetch(url)`. Crucially, those three useState calls and one useEffect call still fully 'belong' to whichever component actually calls useFetch on a given render -- React doesn't care that they're textually written inside a different function; what matters is only that useFetch itself is called, unconditionally, from the top level, on every render of whatever calls it.

